import{_ as t,c as o,o as a,ah as i}from"./chunks/framework.DaDXF32t.js";const g=JSON.parse('{"title":"Installer Update, PTY, and I18n Implementation Plan","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/plans/2026-08-02-installer-update-pty-i18n.md","filePath":"superpowers/plans/2026-08-02-installer-update-pty-i18n.md","lastUpdated":1785749755000}'),n={name:"superpowers/plans/2026-08-02-installer-update-pty-i18n.md"};function l(r,e,s,d,c,p){return a(),o("div",null,e[0]||(e[0]=[i('<h1 id="installer-update-pty-and-i18n-implementation-plan" tabindex="-1">Installer Update, PTY, and I18n Implementation Plan <a class="header-anchor" href="#installer-update-pty-and-i18n-implementation-plan" aria-label="Permalink to “Installer Update, PTY, and I18n Implementation Plan”">​</a></h1><blockquote><p><strong>For agentic workers:</strong> REQUIRED SUB-SKILL: Use superpowers:subagent-driven-development (recommended) or superpowers:executing-plans to implement this plan task-by-task. Steps use checkbox (<code>- [ ]</code>) syntax for tracking.</p></blockquote><p><strong>Goal:</strong> Make the native installer perform real no-op/incremental/full main and OCR updates, expose complete PTY-derived logs in a bilingual TUI, and exit immediately after launching BAAS.</p><p><strong>Architecture:</strong> Repository preparation produces an immutable <code>PreparedRepository</code> for each independently selected MirrorChyan/Git backend, then a barrier feeds the existing main-before-OCR transaction. External terminal-oriented tools publish raw chunks through a platform PTY into one normalized, redacted event log consumed by the TUI and disk sink. Installer-owned messages are keys resolved by an automatically detected Chinese/English catalog.</p><p><strong>Tech Stack:</strong> C++20, CMake/CTest, FTXUI 6.1.9, libcurl, libgit2, Windows ConPTY, POSIX <code>forkpty</code>/<code>openpty</code>, existing transaction/config/uv components.</p><h2 id="global-constraints" tabindex="-1">Global Constraints <a class="header-anchor" href="#global-constraints" aria-label="Permalink to “Global Constraints”">​</a></h2><ul><li>The branch remains based on <code>upstream/master</code>; do not rebase onto <code>origin/master</code>.</li><li>Only <code>setup.toml</code> exists; do not introduce <code>config.toml</code>.</li><li>Backend order is MirrorChyan, installed Git CLI across all ranked sources, then libgit2 across all ranked sources.</li><li>Main and OCR prepare concurrently, then main deploys before OCR under <code>core/ocr/baas_ocr_client/bin</code>.</li><li>A matching local and remote Git SHA must not execute fetch.</li><li>MirrorChyan supports full and incremental packages for both <code>BAAS_repo</code> and platform-specific <code>BAAS_Cpp</code>.</li><li>Do not use <code>MAIN_REPO_SRC_DEV</code> or <code>https://baas-cdn.kiramei.workers.dev</code>.</li><li>All managed uv, Python, cache, temporary, and state paths remain under the install root.</li><li>User-visible external commands use ConPTY on Windows and <code>forkpty</code>/<code>openpty</code> on POSIX; only quiet machine-readable probes may use captured pipes.</li><li>Never print, copy, commit, embed, or pass the MirrorChyan test secret on a command line.</li><li>Preserve unrelated untracked <code>.vscode/</code> and <code>build/</code> content.</li></ul><hr><h3 id="task-1-localized-normalized-event-log" tabindex="-1">Task 1: Localized normalized event log <a class="header-anchor" href="#task-1-localized-normalized-event-log" aria-label="Permalink to “Task 1: Localized normalized event log”">​</a></h3><p><strong>Files:</strong></p><ul><li>Create: <code>deploy/installer/include/baas_installer/localization.hpp</code></li><li>Create: <code>deploy/installer/src/localization.cpp</code></li><li>Create: <code>deploy/installer/include/baas_installer/logging.hpp</code></li><li>Create: <code>deploy/installer/src/logging.cpp</code></li><li>Create: <code>deploy/installer/tests/test_localization.cpp</code></li><li>Create: <code>deploy/installer/tests/test_logging.cpp</code></li><li>Modify: <code>deploy/installer/CMakeLists.txt</code></li></ul><p><strong>Interfaces:</strong></p><ul><li><p>Produces: <code>enum class Language { English, SimplifiedChinese };</code></p></li><li><p>Produces: <code>Language detect_language(const LocaleInputs&amp;)</code> and <code>std::string message(Language, MessageId)</code>.</p></li><li><p>Produces: <code>LogEvent { timestamp, task, backend, severity, text, replace_last }</code>.</p></li><li><p>Produces: <code>ChunkDecoder::consume(std::string_view)</code> and <code>ChunkDecoder::finish()</code> returning normalized logical-line updates.</p></li><li><p>Produces: <code>Redactor::add_secret(std::string)</code> and <code>Redactor::redact(std::string_view)</code>.</p></li><li><p>[ ] <strong>Step 1: Add failing localization tests</strong></p></li></ul><p>Test <code>zh-CN</code>, <code>zh_CN.UTF-8</code>, and Windows language ID <code>0x0804</code> as Chinese; test empty, <code>en_US</code>, and <code>ja_JP</code> as English. Assert the task labels and failure actions exist in both catalogs.</p><ul><li>[ ] <strong>Step 2: Run the localization target and confirm failure</strong></li></ul><p>Run: <code>cmake --build build --config Release --target baas-installer-test-localization</code></p><p>Expected: failure because the target and localization interfaces do not exist.</p><ul><li>[ ] <strong>Step 3: Implement locale detection and complete message catalogs</strong></li></ul><p>Use <code>LocaleInputs { std::string lc_all, lc_messages, lang; unsigned long windows_ui_language; }</code>. Normalize <code>_</code> to <code>-</code>, lowercase the prefix, and select Chinese only when the language prefix equals <code>zh</code>. Provide keys for every setup label, task label, state, error action, and launch result currently rendered by <code>tui.cpp</code>.</p><ul><li>[ ] <strong>Step 4: Add failing chunk and redaction tests</strong></li></ul><p>Feed chunks that split the UTF-8 bytes for <code>下载</code>, contain <code>\\x1b[31m</code>, OSC title sequences, <code>12%\\r34%\\r</code>, <code>abc\\bD\\n</code>, a registered secret, <code>?cdk=value</code>, <code>Authorization: Bearer value</code>, and <code>Cookie: x=value</code>. Assert one replaceable <code>34%</code> line, one committed <code>abD</code> line, valid UTF-8, and no sensitive values.</p><ul><li>[ ] <strong>Step 5: Implement decoder, event formatter, redactor, and thread-safe event store</strong></li></ul><p>Keep incomplete UTF-8 and escape sequences between calls. Treat bare <code>\\r</code> as replacement, <code>\\r\\n</code> as one commit, and backspace as deletion of the previous Unicode code point. Add <code>EventLog::publish(LogEvent)</code>, <code>snapshot()</code>, and <code>set_sink(path)</code>; apply redaction before memory and file sinks.</p><ul><li>[ ] <strong>Step 6: Run focused tests and commit</strong></li></ul><p>Run: <code>cmake --build build --config Release --target baas-installer-test-localization baas-installer-test-logging; ctest --test-dir build -C Release -R &quot;localization|logging&quot; --output-on-failure</code></p><p>Expected: both tests pass.</p><p>Commit: <code>feat(installer): add localized normalized logging</code></p><hr><h3 id="task-2-cross-platform-pty-process-runner" tabindex="-1">Task 2: Cross-platform PTY process runner <a class="header-anchor" href="#task-2-cross-platform-pty-process-runner" aria-label="Permalink to “Task 2: Cross-platform PTY process runner”">​</a></h3><p><strong>Files:</strong></p><ul><li>Modify: <code>deploy/installer/include/baas_installer/process.hpp</code></li><li>Modify: <code>deploy/installer/src/process.cpp</code></li><li>Modify: <code>deploy/installer/tests/test_process.cpp</code></li><li>Modify: <code>deploy/installer/CMakeLists.txt</code></li></ul><p><strong>Interfaces:</strong></p><ul><li><p>Extend <code>ProcessSpec</code> with <code>bool use_pty</code>, <code>std::filesystem::path working_directory</code>, <code>std::chrono::milliseconds timeout</code>, and <code>std::function&lt;void(std::string_view)&gt; on_chunk</code>.</p></li><li><p>Preserve <code>ProcessResult run_process(const ProcessSpec&amp;)</code> for hidden probes.</p></li><li><p>Produce <code>ProcessResult run_terminal_process(const ProcessSpec&amp;)</code> for visible commands.</p></li><li><p>[ ] <strong>Step 1: Add a failing PTY behavior test</strong></p></li></ul><p>Launch the test executable in helper mode so it emits ANSI color, split UTF-8 bytes, and carriage-return progress only when stdout is a terminal. Assert <code>on_chunk</code> receives raw chunks, the child detects a terminal, environment overrides work, and the exit code is retained.</p><ul><li>[ ] <strong>Step 2: Run the process test and confirm failure</strong></li></ul><p>Run: <code>cmake --build build --config Release --target baas-installer-test-process; ctest --test-dir build -C Release -R process --output-on-failure</code></p><p>Expected: failure because <code>run_terminal_process</code> and <code>use_pty</code> are absent.</p><ul><li>[ ] <strong>Step 3: Implement ConPTY</strong></li></ul><p>Dynamically use <code>CreatePseudoConsole</code>, inheritable pipes, <code>STARTUPINFOEXW</code>, <code>PROC_THREAD_ATTRIBUTE_PSEUDOCONSOLE</code>, raw <code>ReadFile</code> chunks, timeout termination, working directory, and the existing UTF-8 environment block. Do not add the CDK or any logger secret to the environment.</p><ul><li>[ ] <strong>Step 4: Implement POSIX PTY</strong></li></ul><p>Use <code>forkpty</code>, apply working directory and environment in the child, call <code>execvp</code> directly without a shell, read the master fd until EOF, and translate <code>waitpid</code> status. Link <code>util</code> only on platforms that require it.</p><ul><li>[ ] <strong>Step 5: Keep hidden probes separate and make visible failures observable</strong></li></ul><p>Retain pipe capture for <code>run_process</code>; route each raw PTY chunk exclusively through <code>on_chunk</code>, while optionally accumulating bounded diagnostic output in <code>ProcessResult.output</code>.</p><ul><li>[ ] <strong>Step 6: Run focused tests and commit</strong></li></ul><p>Run: <code>cmake --build build --config Release --target baas-installer-test-process; ctest --test-dir build -C Release -R process --output-on-failure</code></p><p>Expected: the PTY helper test passes on Windows; POSIX behavior is compiled and exercised by CI.</p><p>Commit: <code>feat(installer): capture tool output through PTY</code></p><hr><h3 id="task-3-git-no-op-and-incremental-update-planner" tabindex="-1">Task 3: Git no-op and incremental update planner <a class="header-anchor" href="#task-3-git-no-op-and-incremental-update-planner" aria-label="Permalink to “Task 3: Git no-op and incremental update planner”">​</a></h3><p><strong>Files:</strong></p><ul><li>Modify: <code>deploy/installer/include/baas_installer/git.hpp</code></li><li>Modify: <code>deploy/installer/src/git.cpp</code></li><li>Modify: <code>deploy/installer/tests/test_git.cpp</code></li></ul><p><strong>Interfaces:</strong></p><ul><li><p>Produce <code>enum class RepositoryMode { Unchanged, Incremental, Full };</code>.</p></li><li><p>Produce <code>RepositoryProbe { bool valid; std::string head; }</code> from <code>probe_repository(path)</code>.</p></li><li><p>Produce <code>GitResult prepare_git_repository(sources, live_path, staging_path, revision, ProcessObserver)</code> with resolved commit and mode.</p></li><li><p>Produce <code>bool apply_git_update(const GitResult&amp;, live_path, InstallTransaction&amp;, error)</code>.</p></li><li><p>Produce <code>using ProcessObserver = std::function&lt;void(std::string_view task, std::string_view backend, std::string_view chunk)&gt;;</code>, shared with uv integration.</p></li><li><p>[ ] <strong>Step 1: Add local-remote no-op tests</strong></p></li></ul><p>Create a bare remote and working clone in the test temp directory. Instrument the command executor and assert equal local/remote heads invoke <code>ls-remote</code> but never <code>fetch</code> or <code>clone</code>, returning <code>RepositoryMode::Unchanged</code> and the real local SHA.</p><ul><li>[ ] <strong>Step 2: Run the Git test and confirm failure</strong></li></ul><p>Run: <code>cmake --build build --config Release --target baas-installer-test-git; ctest --test-dir build -C Release -R git --output-on-failure</code></p><p>Expected: failure because the preparation interfaces do not exist.</p><ul><li>[ ] <strong>Step 3: Implement valid-repository probes and lightweight remote lookup</strong></li></ul><p>Use hidden <code>rev-parse --is-inside-work-tree</code>, <code>rev-parse HEAD</code>, and <code>ls-remote &lt;source&gt; &lt;revision&gt;</code>. Try all sources with installed Git CLI before any libgit2 remote-head lookup. Return unchanged immediately on equal SHAs.</p><ul><li>[ ] <strong>Step 4: Add changed-remote and corrupt-repository tests</strong></li></ul><p>Advance the bare remote, then assert preparation fetches but leaves the live head unchanged until apply. Assert apply reaches the new SHA and retains <code>.git</code>. For invalid <code>.git</code>, assert preparation performs a full staged clone.</p><ul><li>[ ] <strong>Step 5: Implement incremental fetch and full clone paths</strong></li></ul><p>Fetch the resolved SHA into the live repository without checkout during preparation; store old/new SHAs in <code>GitResult</code>. Run visible clone/fetch commands with <code>run_terminal_process</code>. Apply incremental mode with transactional old-head recording and hard reset; deploy full mode from staging.</p><ul><li>[ ] <strong>Step 6: Correct backend ordering and libgit2 parity</strong></li></ul><p>Change clone and remote lookup loops to Git CLI over every source, followed by libgit2 over every source. Implement libgit2 list-heads, fetch/clone, and checkout with the same result modes.</p><ul><li>[ ] <strong>Step 7: Run focused tests and commit</strong></li></ul><p>Run: <code>cmake --build build --config Release --target baas-installer-test-git; ctest --test-dir build -C Release -R git --output-on-failure</code></p><p>Expected: no-op, incremental, corrupt-repository, and backend-order tests pass.</p><p>Commit: <code>feat(installer): add real incremental Git updates</code></p><hr><h3 id="task-4-mirrorchyan-main-ocr-full-and-incremental-packages" tabindex="-1">Task 4: MirrorChyan main/OCR full and incremental packages <a class="header-anchor" href="#task-4-mirrorchyan-main-ocr-full-and-incremental-packages" aria-label="Permalink to “Task 4: MirrorChyan main/OCR full and incremental packages”">​</a></h3><p><strong>Files:</strong></p><ul><li>Modify: <code>deploy/installer/include/baas_installer/mirrorchyan.hpp</code></li><li>Modify: <code>deploy/installer/src/mirrorchyan.cpp</code></li><li>Modify: <code>deploy/installer/tests/test_mirrorchyan.cpp</code></li><li>Modify: <code>deploy/installer/vcpkg.json</code></li><li>Modify: <code>deploy/installer/CMakeLists.txt</code></li></ul><p><strong>Interfaces:</strong></p><ul><li><p>Produce <code>MirrorResource { Main, Ocr }</code> and <code>mirror_latest_url(resource, platform, cdk, current_version, channel)</code>.</p></li><li><p>Produce <code>MirrorPackage { RepositoryMode mode; version; archive; extracted_root; changes; }</code>.</p></li><li><p>Produce <code>prepare_mirror_package(...)</code> and <code>apply_mirror_package(..., InstallTransaction&amp;, error)</code>.</p></li><li><p>Produce <code>MirrorChanges { vector&lt;path&gt; added, modified, deleted; }</code>.</p></li><li><p>[ ] <strong>Step 1: Add failing resource and response tests</strong></p></li></ul><p>Assert main URLs use <code>BAAS_repo</code>, OCR URLs use <code>BAAS_Cpp</code> plus exact <code>windows-x64</code>, <code>linux-x64</code>, <code>macos-x64</code>, or <code>macos-arm64</code>, and CDKs remain URL-encoded without entering error strings.</p><ul><li>[ ] <strong>Step 2: Add failing package safety tests</strong></li></ul><p>Build small ZIP fixtures for a full tree and an incremental <code>changes.json</code>. Assert valid add/modify/delete parsing and rejection of absolute, drive-qualified, <code>..</code>, missing-source, malformed manifest, and bad SHA-256 inputs.</p><ul><li>[ ] <strong>Step 3: Run the MirrorChyan test and confirm failure</strong></li></ul><p>Run: <code>cmake --build build --config Release --target baas-installer-test-mirrorchyan; ctest --test-dir build -C Release -R mirrorchyan --output-on-failure</code></p><p>Expected: failure because resource selection and package application are absent.</p><ul><li>[ ] <strong>Step 4: Implement in-process HTTP and archive extraction</strong></li></ul><p>Use libcurl for latest/download requests and libarchive for ZIP inspection/extraction. Keep CDK only in request memory, pass response text directly to parsing, and report sanitized status/error objects. Validate SHA-256 before opening the archive and validate all paths before extracting or applying.</p><ul><li>[ ] <strong>Step 5: Implement full/incremental preparation and bounded fallback</strong></li></ul><p>Recognize <code>update_type</code>; for a requested incremental update that returns full, retry ten times with 500 ms delays and accept the final validated full package. Represent current-version responses as <code>RepositoryMode::Unchanged</code> without downloading.</p><ul><li>[ ] <strong>Step 6: Implement transactional application</strong></li></ul><p>For incremental mode, journal and apply deletions, additions, and modifications. For full mode, deploy the first child directory. Move <code>.git</code> into transaction backup only during commit and restore it on rollback.</p><ul><li>[ ] <strong>Step 7: Run focused tests and commit</strong></li></ul><p>Run: <code>cmake --build build --config Release --target baas-installer-test-mirrorchyan; ctest --test-dir build -C Release -R mirrorchyan --output-on-failure</code></p><p>Expected: both resources, both package modes, retry, validation, and path-safety tests pass.</p><p>Commit: <code>feat(installer): support MirrorChyan main and OCR updates</code></p><hr><h3 id="task-5-prepared-repository-workflow-and-atomic-state" tabindex="-1">Task 5: Prepared repository workflow and atomic state <a class="header-anchor" href="#task-5-prepared-repository-workflow-and-atomic-state" aria-label="Permalink to “Task 5: Prepared repository workflow and atomic state”">​</a></h3><p><strong>Files:</strong></p><ul><li>Modify: <code>deploy/installer/include/baas_installer/workflow.hpp</code></li><li>Modify: <code>deploy/installer/src/workflow.cpp</code></li><li>Modify: <code>deploy/installer/include/baas_installer/transaction.hpp</code></li><li>Modify: <code>deploy/installer/src/transaction.cpp</code></li><li>Modify: <code>deploy/installer/tests/test_workflow.cpp</code></li><li>Modify: <code>deploy/installer/tests/test_transaction.cpp</code></li></ul><p><strong>Interfaces:</strong></p><ul><li><p>Produce <code>PreparedRepository { RepositoryMode mode; std::string backend; std::string version; std::string prepare_error; std::function&lt;bool(InstallTransaction&amp;, std::string&amp;)&gt; apply; }</code>; rollback remains owned by <code>InstallTransaction</code>.</p></li><li><p>Change services to <code>prepare_main() -&gt; PreparedRepository</code> and <code>prepare_ocr() -&gt; PreparedRepository</code>.</p></li><li><p>Keep <code>install_or_update(config, paths, services)</code> as the orchestration entry point.</p></li><li><p>[ ] <strong>Step 1: Add failing workflow state tests</strong></p></li></ul><p>Assert preparation runs concurrently; a failure joins the peer and performs zero live mutations; successful preparation applies main before OCR; unchanged units perform no apply; config receives both versions only after verify and uv succeed.</p><ul><li>[ ] <strong>Step 2: Add failing rollback tests</strong></li></ul><p>Force OCR apply, verify, and uv failures separately. Assert prior main/OCR bytes and committed heads are restored, moved <code>.git</code> directories return, and prior <code>setup.toml</code> SHA/version fields remain byte-identical.</p><ul><li>[ ] <strong>Step 3: Run workflow and transaction tests to confirm failure</strong></li></ul><p>Run: <code>cmake --build build --config Release --target baas-installer-test-workflow baas-installer-test-transaction; ctest --test-dir build -C Release -R &quot;workflow|transaction&quot; --output-on-failure</code></p><p>Expected: new ordering and rollback assertions fail.</p><ul><li>[ ] <strong>Step 4: Implement immutable preparation results and barrier</strong></li></ul><p>Run main/OCR producers via <code>std::async</code>, collect both results, cancel only through shared cooperative state, and enter commit only when both succeed. Emit checking, skipped, ready, applying, complete, fallback, and failed events with task/backend metadata.</p><ul><li>[ ] <strong>Step 5: Extend transaction journal and atomic config commit</strong></li></ul><p>Journal Git old heads, Mirror file backups, created paths, deleted paths, and <code>.git</code> moves. Apply main then OCR, verify, sync uv, set both in-memory versions, and call <code>save_config_atomic</code> once. On failure, reverse every applied journal entry.</p><ul><li>[ ] <strong>Step 6: Run focused tests and commit</strong></li></ul><p>Run: <code>cmake --build build --config Release --target baas-installer-test-workflow baas-installer-test-transaction; ctest --test-dir build -C Release -R &quot;workflow|transaction&quot; --output-on-failure</code></p><p>Expected: concurrency, order, no-op, persistence, and rollback tests pass.</p><p>Commit: <code>refactor(installer): orchestrate prepared repository updates</code></p><hr><h3 id="task-6-unified-bilingual-tui-and-immediate-exit" tabindex="-1">Task 6: Unified bilingual TUI and immediate exit <a class="header-anchor" href="#task-6-unified-bilingual-tui-and-immediate-exit" aria-label="Permalink to “Task 6: Unified bilingual TUI and immediate exit”">​</a></h3><p><strong>Files:</strong></p><ul><li>Modify: <code>deploy/installer/include/baas_installer/tui.hpp</code></li><li>Modify: <code>deploy/installer/src/tui.cpp</code></li><li>Modify: <code>deploy/installer/tests/test_tui.cpp</code></li></ul><p><strong>Interfaces:</strong></p><ul><li><p><code>InstallerViewModel(Language, shared_ptr&lt;EventLog&gt;, bool setup_required)</code> owns localized task snapshots and scroll state.</p></li><li><p><code>append_event(LogEvent)</code> updates the unified log, replacing the last logical line when requested.</p></li><li><p><code>run_tui(...)</code> exits the FTXUI loop on successful BAAS launch; launch failure remains retryable.</p></li><li><p>[ ] <strong>Step 1: Add failing TUI model tests</strong></p></li></ul><p>Assert Chinese and English labels, static running marker, real-progress-only gauge, more than eight retained history lines, carriage-return replacement, scroll offsets, no <code>Succeeded</code> page transition, and launch-success exit request.</p><ul><li>[ ] <strong>Step 2: Run the TUI test and confirm failure</strong></li></ul><p>Run: <code>cmake --build build --config Release --target baas-installer-test-tui; ctest --test-dir build -C Release -R tui --output-on-failure</code></p><p>Expected: failure because the existing model truncates logs, animates a spinner, and shows a success page.</p><ul><li>[ ] <strong>Step 3: Implement the unified log layout</strong></li></ul><p>Remove ticker/frame state and <code>spinner(...)</code>. Render task states with fixed symbols and a large bordered log pane tagged <code>[time][task][backend][level]</code>. Tail-follow by default; add keyboard and mouse scrolling without splitting Git into a separate panel.</p><ul><li>[ ] <strong>Step 4: Localize every installer-owned string</strong></li></ul><p>Replace literal Chinese text and English-detail substring inference with <code>MessageId</code> and explicit status/progress events. Leave decoded child output unchanged except redaction and tagging.</p><ul><li>[ ] <strong>Step 5: Implement launch-success exit behavior</strong></li></ul><p>Represent installation commit and BAAS launch as separate outcomes. Keep the failure view for launch retry without transaction rollback. Post the FTXUI exit closure immediately after a successful detached launch; remove the success screen and manual Exit requirement.</p><ul><li>[ ] <strong>Step 6: Run focused tests and commit</strong></li></ul><p>Run: <code>cmake --build build --config Release --target baas-installer-test-tui; ctest --test-dir build -C Release -R tui --output-on-failure</code></p><p>Expected: bilingual model/layout and launch-flow tests pass with no spinner.</p><p>Commit: <code>feat(installer): unify bilingual live TUI logs</code></p><hr><h3 id="task-7-production-wiring-uv-logs-migration-and-ci" tabindex="-1">Task 7: Production wiring, uv logs, migration, and CI <a class="header-anchor" href="#task-7-production-wiring-uv-logs-migration-and-ci" aria-label="Permalink to “Task 7: Production wiring, uv logs, migration, and CI”">​</a></h3><p><strong>Files:</strong></p><ul><li>Modify: <code>deploy/installer/src/main.cpp</code></li><li>Modify: <code>deploy/installer/src/uv_environment.cpp</code></li><li>Modify: <code>deploy/installer/include/baas_installer/uv_environment.hpp</code></li><li>Modify: <code>deploy/installer/tests/test_uv_environment.cpp</code></li><li>Modify: <code>deploy/installer/tests/manual/verify_local_migration.ps1</code></li><li>Modify: <code>deploy/installer/README.md</code></li><li>Modify: <code>deploy/installer/README_CN.md</code></li><li>Modify: <code>.github/workflows/build-installer.yml</code></li></ul><p><strong>Interfaces:</strong></p><ul><li><p>Main constructs one redacted <code>EventLog</code>, process observer, main preparer, and OCR preparer.</p></li><li><p>uv synchronization accepts the shared <code>ProcessObserver</code> and uses PTY for every visible uv command.</p></li><li><p>Detached launch returns success independently from the committed installation result.</p></li><li><p>[ ] <strong>Step 1: Add failing uv observer tests</strong></p></li></ul><p>Inject a fake process executor and assert every visible uv install/venv/pip command requests PTY, passes the root-local environment map, and forwards chunks to the observer. Assert quiet version/path probes stay hidden.</p><ul><li>[ ] <strong>Step 2: Run uv tests and confirm failure</strong></li></ul><p>Run: <code>cmake --build build --config Release --target baas-installer-test-uv; ctest --test-dir build -C Release -R uv --output-on-failure</code></p><p>Expected: failure because uv does not accept the shared observer or require PTY.</p><ul><li>[ ] <strong>Step 3: Wire production repository selection and logging</strong></li></ul><p>Replace direct curl/tar and always-clone lambdas in <code>main.cpp</code> with main/OCR preparers. For each unit, try MirrorChyan when configured, then Git CLI, then libgit2. Send every status and raw chunk to the same event log; never log request URLs containing <code>cdk</code>.</p><ul><li>[ ] <strong>Step 4: Route uv through PTY and keep all paths portable</strong></li></ul><p>Pass the observer into <code>sync_portable_uv</code>, use <code>run_terminal_process</code> for visible commands, and retain every existing <code>UV_*</code>, <code>XDG_*</code>, temp, venv, Python, and cache override rooted at the executable directory.</p><ul><li>[ ] <strong>Step 5: Update migration and documentation</strong></li></ul><p>Make the migration script copy the source install, never mutate it, validate no-fetch behavior when heads match, validate OCR placement and Git/Mirror metadata rules, validate root-local uv state, launch BAAS, and record sanitized evidence. Document bilingual locale selection, unified PTY logs, update modes, and immediate exit.</p><ul><li>[ ] <strong>Step 6: Run the full local test suite</strong></li></ul><p>Run: <code>cmake --build build --config Release; ctest --test-dir build -C Release --output-on-failure</code></p><p>Expected: every installer test passes.</p><ul><li>[ ] <strong>Step 7: Run local Git integration and disposable migration</strong></li></ul><p>Run the local bare-remote no-op/update integration. Then run <code>verify_local_migration.ps1</code> against a fresh copy of <code>D:\\Amusement\\BAAS_NEW</code>, never the original. Verify the normalized log contains Git and uv output, contains no spinner artifacts, and BAAS launch closes the installer.</p><ul><li>[ ] <strong>Step 8: Run the explicitly configured MirrorChyan integration safely</strong></li></ul><p>Read the operator-provided secret file only inside the test process. Exercise main and OCR in disposable roots, then scan repository diff, logs, captured test output, staging, and build artifacts byte-for-byte for the secret. Print only the boolean scan result and sanitized resource outcomes.</p><ul><li>[ ] <strong>Step 9: Commit production integration</strong></li></ul><p>Commit: <code>feat(installer): integrate incremental bilingual installer</code></p><ul><li>[ ] <strong>Step 10: Push and verify four-platform CI</strong></li></ul><p>Push <code>feat/cpp-tui-installer</code>, wait for Windows x86_64, Linux x86_64, macOS x86_64, and macOS arm64 tests/builds, and inspect sanitized logs on any failure. Confirm the tag-only job still publishes executables and <code>SHA256SUMS</code> as GitHub Release assets.</p>',158)]))}const m=t(n,[["render",l]]);export{g as __pageData,m as default};
